<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { PhTrash } from '@phosphor-icons/vue'
import Notice from '../components/Notice.vue'
import LoadingState from '../components/LoadingState.vue'
import MaterialPicker from '../components/MaterialPicker.vue'
import InputPreview from '../components/InputPreview.vue'
import type { Manifest } from '../components/InputPreview.vue'
import ModelRecovery from '../components/ModelRecovery.vue'
import { training, writeTraining, ApiError } from '../api/training'
import { localDate } from '../models/training'
import type { Page } from '../models/training'
type Row = Record<string, any>
const route = useRoute(), router = useRouter(), id = computed(() => String(route.params.id || ''))
const stories = ref<Row[]>([]), cursor = ref<string | null>(null), story = ref<Row | null>(null), kind = ref('STAR'), materialIds = ref<string[]>([]), fields = ref<Row>({}), serverFields = ref<Row>({}), expression = ref(''), manifest = ref<Manifest | null>(null)
const history = ref<Row[]>([]), historyCursor = ref<string | null>(null), historical = ref<Row | null>(null), questionTemplate = ref('PROJECT_CHALLENGE'), ackSource = ref(false), confirmations = ref<Row>({})
const loading = ref(true), busy = ref(false), error = ref(''), message = ref(''), recovery = ref<ApiError | null>(null)
const deletingId = ref('')
const templates: Record<string, string[]> = { STAR: ['situation', 'task', 'action', 'result', 'reflection'], INTRO: ['targetRole', 'background', 'experience', 'contribution', 'aspiration'] }
const labels: Record<string, string> = { situation: '情境：发生了什么', task: '任务：需要解决什么', action: '个人行动：我具体做了什么', result: '结果：实际发生的变化', reflection: '复盘：局限与下次改进', targetRole: '目标岗位', background: '个人背景', experience: '相关真实经历', contribution: '个人贡献', aspiration: '下一步诉求' }
const storyStatusLabels: Record<string, string> = { DRAFT: '草稿', CONFIRMED: '已确认', ARCHIVED: '已归档' }
const originLabels: Record<string, string> = { MATERIAL_QUOTE: '材料逐字引用', USER_ASSERTION: '本人声明', MODEL_DRAFT: '模型表达草稿 · 未确认', MISSING: '事实待补充' }
const questions: Record<string, string> = { PROJECT_CHALLENGE: '项目困难与个人行动', TEAM_CONFLICT: '处理项目分歧', SELF_INTRO: '面向岗位的自我介绍', PROJECT_VALUE: '经历与岗位的关联' }
const fieldIds = computed(() => templates[story.value?.templateKind || kind.value] || [])
function fail(e: unknown) { error.value = e instanceof Error ? e.message : '操作失败，本页编辑保留。'; recovery.value = e instanceof ApiError ? e : null }
function resetFields() { fields.value = Object.fromEntries((templates[kind.value] || []).map(k => [k, { text: '', originType: 'MISSING' }])); confirmations.value = {}; expression.value = '' }
resetFields()
function setCurrent(s: Row, keepLocal = false) { story.value = s; serverFields.value = structuredClone(s.fields); const current = { fields: s.fields, expression: s.currentVersionDetail?.expressionDraft || '' }; let local: Row | null = null; if (keepLocal) try { local = JSON.parse(sessionStorage.getItem(`v2:story:${id.value}`) || 'null') } catch { /* 从服务端恢复。 */ } fields.value = structuredClone(local?.fields || current.fields); expression.value = local?.expression ?? current.expression; materialIds.value = s.materialIds || []; confirmations.value = {}; for (const k of fieldIds.value) confirmations.value[k] = { confirmed: false, notApplicable: false, reason: '' }; questionTemplate.value = s.templateKind === 'STAR' ? 'PROJECT_CHALLENGE' : 'SELF_INTRO'; if (['FAILED', 'INTERRUPTED', 'RUNNING'].includes(s.generationState)) recovery.value = Object.assign(new ApiError('故事生成尚未完成'), { operationId: s.operationId }) }
watch([fields, expression], () => { if (id.value && story.value?.status !== 'ARCHIVED') try { sessionStorage.setItem(`v2:story:${id.value}`, JSON.stringify({ fields: fields.value, expression: expression.value })) } catch { /* 本页编辑保留。 */ } }, { deep: true })
async function load(more = false) { loading.value = true; try { if (id.value) setCurrent(await training<Row>(`/stories/${id.value}`), true); else { const p = await training<Page<Row>>(`/stories?limit=20&cursor=${encodeURIComponent(more ? cursor.value || '' : '')}`); stories.value = more ? [...stories.value, ...p.items] : p.items; cursor.value = p.nextCursor } } catch (e) { fail(e) } finally { loading.value = false } }
function payloadFields() { return Object.fromEntries(fieldIds.value.map(k => [k, { text: fields.value[k]?.text || '', originType: fields.value[k]?.text?.trim() ? fields.value[k]?.originType === 'MISSING' ? 'USER_ASSERTION' : fields.value[k]?.originType || 'USER_ASSERTION' : 'MISSING' }])) }
const dirty = computed(() => !!story.value && (JSON.stringify(payloadFields()) !== JSON.stringify(Object.fromEntries(Object.entries(story.value.fields).map(([k, f]) => [k, { text: (f as any).text, originType: (f as any).originType }]))) || expression.value !== (story.value.currentVersionDetail?.expressionDraft || '')))
async function save() { busy.value = true; error.value = ''; try { const s = await writeTraining<Row>(id.value ? `/stories/${id.value}/versions` : '/stories', { ...(id.value ? { expectedVersion: story.value!.revision } : { templateKind: kind.value, materialIds: materialIds.value }), fields: payloadFields(), expressionDraft: expression.value }); message.value = '已保存独立故事版本，旧版及确认保留。'; if (!id.value) await router.push(`/stories/${s.id}`); else { sessionStorage.removeItem(`v2:story:${id.value}`); setCurrent(await training(`/stories/${id.value}`)) } } catch (e) { fail(e); if (id.value) try { serverFields.value = (await training<Row>(`/stories/${id.value}`)).fields } catch { /* 不覆盖本页编辑。 */ } } finally { busy.value = false } }
async function confirm() { busy.value = true; try { await writeTraining(`/stories/${id.value}/confirm`, { expectedVersion: story.value!.revision, storyVersion: story.value!.currentVersion, confirmations: confirmations.value, acknowledgeSourcesChanged: ackSource.value }); sessionStorage.removeItem(`v2:story:${id.value}`); setCurrent(await training(`/stories/${id.value}`)); message.value = '已保存你的逐字段确认；这是本人声明，不代表系统外部核验。' } catch (e) { fail(e) } finally { busy.value = false } }
async function prepare() { busy.value = true; try { manifest.value = await writeTraining<Manifest>(`/stories/${id.value}/input-preparations`, { expectedVersion: story.value!.revision, materialIds: materialIds.value }); message.value = '预览使用已保存的本人声明与材料；本页未保存修改不会发送。' } catch (e) { fail(e) } finally { busy.value = false } }
async function generate() { if (!manifest.value) return; busy.value = true; try { const s = await writeTraining<Row>(`/stories/${id.value}/draft-generation`, { expectedVersion: story.value!.revision, manifestId: manifest.value.manifestId, manifestHash: manifest.value.manifestHash }); sessionStorage.removeItem(`v2:story:${id.value}`); setCurrent(s); manifest.value = null; message.value = '生成已另存新草稿，事实仍需逐字段核对。' } catch (e) { fail(e) } finally { busy.value = false } }
async function recoverGenerated() { const keepLocal = dirty.value; if (!keepLocal) sessionStorage.removeItem(`v2:story:${id.value}`); recovery.value = null; error.value = ''; await load(); message.value = keepLocal ? '生成结果已保存，本页编辑仍保留；展开服务端事实版本核对。' : '已载入保存的生成结果，请逐字段核对。' }
async function archive() { busy.value = true; try { await writeTraining(`/stories/${id.value}/archive`, { expectedVersion: story.value!.revision, restore: story.value!.status === 'ARCHIVED' }); await load() } catch (e) { fail(e) } finally { busy.value = false } }
async function deleteStory(item: Row) {
  const title = `${item.templateKind === 'STAR' ? 'STAR 项目故事' : '自我介绍'} · 版本 ${item.currentVersion}`
  if (busy.value || !window.confirm(`删除“${title}”？删除后将从故事库移除，已有独立作答与练习记录会保留。`)) return
  busy.value = true; deletingId.value = item.id; error.value = ''; recovery.value = null; message.value = ''
  try {
    await writeTraining(`/stories/${item.id}`, { expectedVersion: item.revision }, 'DELETE')
    stories.value = stories.value.filter(s => s.id !== item.id)
    sessionStorage.removeItem(`v2:story:${item.id}`)
    message.value = '故事已删除，已有独立作答与练习记录保留。'
  } catch (e) { fail(e) }
  finally { busy.value = false; deletingId.value = '' }
}
async function versions(more = false) { try { const p = await training<Page<Row>>(`/stories/${id.value}/versions?limit=20&cursor=${encodeURIComponent(more ? historyCursor.value || '' : '')}`); history.value = more ? [...history.value, ...p.items] : p.items; historyCursor.value = p.nextCursor } catch (e) { fail(e) } }
async function practice(versionId: string) { busy.value = true; try { const c = await writeTraining<Row>('/practice-cases', { sourceKind: 'STORY', sourceId: id.value, storyVersionId: versionId, questionTemplateId: questionTemplate.value }); await router.push(`/practice/${c.id}`) } catch (e) { fail(e) } finally { busy.value = false } }
onMounted(() => load())
</script>
<template><div class="page training-page"><div class="page-heading"><h1>让真实经历，有条理地被听懂。</h1><p>自我介绍与 STAR 故事分别保存。缺事实时留空待补充，不编造个人职责和成果。</p></div><Notice :message="error" kind="error" /><Notice :message="message" /><ModelRecovery :error="recovery" @recovered="recoverGenerated" /><LoadingState v-if="loading" label="正在读取故事版本…" />
<div v-if="!loading" class="training-reading-layout"><section class="panel training-flow"><div v-if="!id"><label for="story-kind">整理方式</label><select id="story-kind" v-model="kind" @change="resetFields"><option value="STAR">STAR 项目故事</option><option value="INTRO">自我介绍</option></select></div><div v-else class="training-toolbar"><h2>{{ story?.templateKind === 'INTRO' ? '自我介绍' : 'STAR 故事' }} · 版本 {{ story?.currentVersion }}</h2><span class="badge badge-gray">{{ storyStatusLabels[story?.status || 'DRAFT'] }}</span><span v-if="story?.mock" class="badge badge-orange">Mock 流程</span><RouterLink to="/stories" class="text-link">返回故事库</RouterLink></div><p v-if="story?.sourcesChanged" class="notice">来源版本已变化，历史快照仍保留。确认前需核对当时事实。</p>
<div v-for="k in fieldIds" :key="k" class="training-story-field"><label :for="`story-${k}`">{{ labels[k] }}</label><textarea :id="`story-${k}`" v-model="fields[k].text" :readonly="busy || story?.status === 'ARCHIVED'" maxlength="6000" rows="4" placeholder="待补充：请填写真实事实，不确定的数字保持空缺。" /><label :for="`origin-${k}`" class="tiny muted">此字段来源</label><select :id="`origin-${k}`" v-model="fields[k].originType" :disabled="busy || story?.status === 'ARCHIVED'"><option value="MISSING">事实待补充</option><option value="USER_ASSERTION">本人声明</option><option value="MODEL_DRAFT">未确认表达草稿</option><option v-if="story?.fields[k]?.originType === 'MATERIAL_QUOTE'" value="MATERIAL_QUOTE">材料逐字引用（只允许沿用原文）</option></select><p class="tiny muted">当前已保存：{{ originLabels[story?.fields[k]?.originType || 'MISSING'] }}</p><details v-if="story?.fields[k]?.sourceRefs?.length"><summary>查看来源引用</summary><p v-for="(r, i) in story.fields[k].sourceRefs" :key="i">{{ r.quote }} · 来源 {{ r.snapshotId }}</p></details></div><p class="tiny muted">事实字段合计最多 6000 字符，表达稿最多 6000 字符。保存更改会新建版本，并要求重新确认。</p><div><label for="story-expression">表达稿（不作为事实证明）</label><textarea id="story-expression" v-model="expression" :readonly="busy || story?.status === 'ARCHIVED'" maxlength="6000" rows="5" /></div><details v-if="id && JSON.stringify(payloadFields()) !== JSON.stringify(Object.fromEntries(Object.entries(serverFields).map(([k, f]) => [k, { text: f.text, originType: f.originType }])))"><summary>查看服务端事实版本（本页编辑保留）</summary><div v-for="k in fieldIds" :key="k"><h3>{{ labels[k] }}</h3><pre>{{ serverFields[k]?.text || '待补充' }}</pre></div></details><button v-if="story?.status !== 'ARCHIVED'" class="btn btn-primary" :disabled="busy" @click="save">{{ id ? '保存为新版本' : '保存第一版故事' }}</button>
<details v-if="id" @toggle="($event.target as HTMLDetailsElement).open && versions()"><summary>查看所有故事版本</summary><div v-for="h in history" :key="h.id" class="training-quote"><button class="text-link" @click="training<Row>(`/stories/${id}/versions/${h.id}`).then(r => historical = r).catch(fail)">版本 {{ h.version }} · {{ h.status === 'CONFIRMED' ? '已确认' : '草稿' }} · {{ localDate(h.createdAt) }}</button></div><button v-if="historyCursor" class="text-link" @click="versions(true)">加载更多版本</button><section v-if="historical"><h3>历史版本 {{ historical.version }}</h3><div v-for="k in fieldIds" :key="k" class="training-quote"><strong>{{ labels[k] }} · {{ originLabels[historical.fields[k]?.originType] }}</strong><pre>{{ historical.fields[k]?.text || '待补充' }}</pre></div><pre>{{ historical.expressionDraft }}</pre><button v-if="historical.status === 'CONFIRMED' && story?.status !== 'ARCHIVED'" class="btn btn-secondary" :disabled="busy" @click="practice(historical.id)">按此已确认历史版本练习</button></section></details></section>
<aside class="panel training-flow"><p v-if="dirty" class="notice">本页有未保存修改。请先保存为新版本，再预览生成或逐字段确认，避免丢失编辑。</p><h2>{{ !id ? '从真实材料开始' : '核对事实，再用于练习' }}</h2><MaterialPicker v-model="materialIds" /><p class="tiny muted">材料可以只作为参考。没有事实的字段仍显示待补充；模型表达稿不能自动转为本人声明。</p><template v-if="id && story?.status !== 'ARCHIVED'"><button class="btn btn-secondary" :disabled="busy || dirty" @click="prepare">预览已保存事实与所选材料</button><InputPreview v-if="manifest" :manifest="manifest" /><button v-if="manifest" class="btn btn-primary" :disabled="busy || dirty" @click="generate">确认发送并调用模型生成新草稿</button><section v-if="story?.status === 'DRAFT'"><h3>逐字段确认当前已保存版本</h3><p class="tiny muted">确认不会包含本页未保存编辑。个人行动或贡献不可标为不适用。</p><div v-for="k in fieldIds" :key="k" class="training-quote"><label class="training-inline-check"><input v-model="confirmations[k].confirmed" type="checkbox" />{{ labels[k] }}：我确认所存事实</label><template v-if="!['action', 'contribution'].includes(k) && !story!.fields[k].text"><label class="training-inline-check"><input v-model="confirmations[k].notApplicable" type="checkbox" />空缺字段不适用</label><label v-if="confirmations[k].notApplicable" :for="`na-${k}`">不适用原因</label><input v-if="confirmations[k].notApplicable" :id="`na-${k}`" v-model="confirmations[k].reason" maxlength="1000" /></template></div><label v-if="story?.sourcesChanged" class="training-inline-check"><input v-model="ackSource" type="checkbox" />我已核对并接受该历史来源版本边界</label><button class="btn btn-primary" :disabled="busy || dirty" @click="confirm">确认这个已保存版本</button></section><section v-if="story?.status === 'CONFIRMED'"><label for="story-question">练习问题</label><select id="story-question" v-model="questionTemplate"><option v-for="key in story.templateKind === 'STAR' ? ['PROJECT_CHALLENGE', 'TEAM_CONFLICT'] : ['SELF_INTRO', 'PROJECT_VALUE']" :key="key" :value="key">{{ questions[key] }}</option></select><p class="tiny muted">故事已展示，属于辅助准备。练习评价文本结构、个人行动与事实一致性，不评价口头表现。</p><button class="btn btn-primary" :disabled="busy" @click="practice(story!.currentVersionId)">用此确认版进入独立作答</button></section></template><button v-if="id" class="btn btn-ghost" :disabled="busy" @click="archive">{{ story?.status === 'ARCHIVED' ? '恢复故事' : '归档故事（保留历史）' }}</button></aside></div>
<section v-if="!id && !loading" class="panel training-section"><h2>已保存故事</h2><p v-if="!stories.length" class="muted">还没有故事。从一段真实经历开始，缺失事实可以稍后补充。</p><article v-for="s in stories" :key="s.id" class="training-list-row"><div><h3>{{ s.templateKind === 'STAR' ? 'STAR 项目故事' : '自我介绍' }} · 版本 {{ s.currentVersion }}</h3><p>{{ storyStatusLabels[s.status] }} · {{ localDate(s.updatedAt) }}</p></div><div class="story-list-actions"><RouterLink :to="`/stories/${s.id}`" class="btn btn-secondary">打开故事与版本</RouterLink><button type="button" class="btn btn-ghost story-delete" :disabled="busy" @click="deleteStory(s)"><PhTrash :size="16" />{{ deletingId === s.id ? '删除中…' : '删除' }}</button></div></article><button v-if="cursor" class="text-link" @click="load(true)">加载更多故事</button></section></div></template>

<style scoped>
.story-list-actions { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.story-delete { color: var(--danger); }
</style>
